cd -- "$1" || exit 3; shift; a() { q=.; z=$1; while :; do case $z in */*) q=$q/${z%%/*}; z=${z#*/} ;; *) return 0 ;; esac; if [ -L "$q" ]; then return 1; elif [ -d "$q" ]; then [ -x "$q" ] || return 1; elif [ -e "$q" ]; then return 1; else return 2; fi; done; }; for p in "$@"; do case $p in ''|..|../*|*/../*|*/..|/*|./*|*/./*|*/.|.) printf 'R/%s\n' "$p"; exit 1 ;; esac; a "$p" || [ $? = 2 ] || { printf 'R/%s\n' "$p"; exit 1; }; [ -L "$p" ] && { printf 'R/%s\n' "$p"; exit 1; }; mkdir -p -- "$p" 2>/dev/null || { printf 'R/%s\n' "$p"; exit 1; }; printf 'D/%s\n' "$p"; done